// Simulation: a project bootstrap checklist run in order
const steps = [
  { name: 'Clarify requirements', done: true },
  { name: 'Pick stack & scaffold repo', done: true },
  { name: 'Set up lint + CI', done: true },
  { name: 'Build the core feature end-to-end', done: false },
  { name: 'Write tests for critical paths', done: false },
  { name: 'Deploy to staging', done: false },
];

const next = steps.find(s => !s.done);
const progress = Math.round(steps.filter(s => s.done).length / steps.length * 100);

steps.forEach((s, i) => console.log((s.done ? '[x] ' : '[ ] ') + (i + 1) + '. ' + s.name));
console.log('Progress: ' + progress + '%'); // Progress: 50%
console.log('Next step: ' + next.name); // Next step: Build the core feature end-to-end

// Score each stack option against weighted criteria (1-5)
const weights = { teamSkill: 5, hiring: 3, ecosystem: 3, performance: 2 };
const options = {
  'Next.js + Node': { teamSkill: 5, hiring: 5, ecosystem: 5, performance: 4 },
  'Laravel + Blade': { teamSkill: 2, hiring: 3, ecosystem: 4, performance: 3 },
  'Go + HTMX': { teamSkill: 1, hiring: 2, ecosystem: 3, performance: 5 },
};

const score = o => Object.entries(weights)
  .reduce((sum, [k, w]) => sum + o[k] * w, 0);

const ranked = Object.entries(options)
  .map(([name, o]) => ({ name, score: score(o) }))
  .sort((a, b) => b.score - a.score);

ranked.forEach(r => console.log(r.name + ': ' + r.score));
// Next.js + Node: 63
// Laravel + Blade: 37
// Go + HTMX: 30
console.log('Pick: ' + ranked[0].name); // Pick: Next.js + Node

// Three-point (PERT) estimate: (optimistic + 4*likely + pessimistic) / 6
const tasks = [
  { name: 'Login API', o: 1, m: 2, p: 5 },
  { name: 'Login UI', o: 1, m: 2, p: 3 },
  { name: 'Payment integration', o: 3, m: 5, p: 12 },
];

let total = 0;
for (const t of tasks) {
  const est = (t.o + 4 * t.m + t.p) / 6;
  total += est;
  console.log(t.name + ': ' + est.toFixed(1) + ' days');
}
// Login API: 2.3 days
// Login UI: 2.0 days
// Payment integration: 5.8 days
const buffer = total * 0.2; // 20% buffer for meetings, review, surprises
console.log('Total: ' + total.toFixed(1) + ' + buffer ' + buffer.toFixed(1) + ' = ' + (total + buffer).toFixed(1) + ' days');
// Total: 10.1 + buffer 2.0 = 12.1 days

// Simulation: when does the HTML get generated in each strategy?
let dbTitle = 'Product v1';
const render = () => '<h1>' + dbTitle + '</h1>';

const ssg = render();                       // SSG: built once at build time
let isrCache = { html: render(), at: 0 };   // ISR: cached, rebuilt after revalidate window

function ssr() { return render(); }         // SSR: every request
function csr() { return '<div id="root"></div> (fetch + render in browser)'; } // CSR: empty shell
function isr(now, revalidate = 60) {
  if (now - isrCache.at > revalidate) isrCache = { html: render(), at: now };
  return isrCache.html;
}

dbTitle = 'Product v2'; // data changes after build
console.log('SSG @t=10:', ssg);          // <h1>Product v1</h1>   (stale until redeploy)
console.log('SSR @t=10:', ssr());        // <h1>Product v2</h1>   (always fresh)
console.log('CSR @t=10:', csr());
console.log('ISR @t=10:', isr(10));      // <h1>Product v1</h1>   (inside window)
console.log('ISR @t=70:', isr(70));      // <h1>Product v2</h1>   (revalidated)

// Simulation: hydration = attaching events to HTML the server already sent
const serverHTML = '<button id="buy">Buy (0)</button>';
const handlers = {};
