// Simulation: tiny Virtual DOM diff - compute the minimal patches
const oldTree = { tag: 'ul', children: [
  { tag: 'li', text: 'Milk' },
  { tag: 'li', text: 'Eggs' },
] };
const newTree = { tag: 'ul', children: [
  { tag: 'li', text: 'Milk' },
  { tag: 'li', text: 'Eggs (x12)' },
  { tag: 'li', text: 'Bread' },
] };

function diff(a, b, path = 'ul') {
  const patches = [];
  b.children.forEach((child, i) => {
    const old = a.children[i];
    if (!old) patches.push('ADD ' + path + '>li[' + i + '] "' + child.text + '"');
    else if (old.text !== child.text) patches.push('UPDATE ' + path + '>li[' + i + '] -> "' + child.text + '"');
  });
  return patches;
}

console.log(diff(oldTree, newTree));
// [ 'UPDATE ul>li[1] -> "Eggs (x12)"', 'ADD ul>li[2] "Bread"' ]
// Only 2 real DOM operations, the first <li> is untouched.

import { useState, useEffect, useRef, useMemo } from 'react';

function App() {
  const [query, setQuery] = useState('');                // state
  const [seconds, setSeconds] = useState(0);
  const inputRef = useRef(null);                         // DOM handle, no re-render

  useEffect(() => {                                      // side effect + cleanup
    const id = setInterval(() => setSeconds(s => s + 1), 1000);
    return () => clearInterval(id);
  }, []);

  const products = ['Keyboard', 'Mouse', 'Monitor', 'Mic'];
  const results = useMemo(() => {                        // cached until query changes
    console.log('filtering for "' + query + '"');
    return products.filter(p => p.toLowerCase().includes(query.toLowerCase()));
  }, [query]);

  return (
    <div style={{ fontFamily: 'sans-serif', padding: 12 }}>
      <input ref={inputRef} value={query} onChange={e => setQuery(e.target.value)} placeholder="Search..." />
      <button onClick={() => inputRef.current.focus()}>Focus</button>
      <p>Open for {seconds}s</p>
      <ul>{results.map(r => <li key={r}>{r}</li>)}</ul>
    </div>
  );
}

import { createContext, useContext, useReducer } from 'react';

// Context + useReducer: fine for small, local client state (a cart)
const CartContext = createContext(null);

function cartReducer(items, action) {
  if (action.type === 'add') return [...items, action.item];
  if (action.type === 'clear') return [];
  return items;
}

function CartProvider({ children }) {
  const [items, dispatch] = useReducer(cartReducer, []);
  return <CartContext.Provider value={{ items, dispatch }}>{children}</CartContext.Provider>;
}

function Header() {
  const { items } = useContext(CartContext);
  return <h3>Cart ({items.length})</h3>;
}

function Shelf() {
  const { dispatch } = useContext(CartContext);
  return (
    <>
      <button onClick={() => dispatch({ type: 'add', item: 'Keyboard' })}>Add keyboard</button>
      <button onClick={() => dispatch({ type: 'clear' })}>Clear</button>
    </>
  );
}

function App() {
  return <CartProvider><Header /><Shelf /></CartProvider>;
}

