import { useState, useRef } from 'react';

function App() {
  // Controlled: React state is the single source of truth
  const [email, setEmail] = useState('');
  const emailValid = email.includes('@');

  // Uncontrolled: the DOM holds the value, we read it on demand
  const nameRef = useRef(null);
  const [submitted, setSubmitted] = useState('');

  return (
    <div style={{ fontFamily: 'sans-serif' }}>
      <input value={email} onChange={e => setEmail(e.target.value)} placeholder="email (controlled)" />
      <span style={{ color: emailValid ? 'green' : 'red' }}> {emailValid ? 'valid' : 'needs @'}</span>
      <br />
      <input ref={nameRef} defaultValue="Sara" />
      <button onClick={() => { setSubmitted(nameRef.current.value); console.log('read from DOM:', nameRef.current.value); }}>
        Read name
      </button>
      <p>Submitted: {submitted}</p>
    </div>
  );
}

