// Simulation: how a server decides CORS (the browser enforces the result)
const allowed = ['https://shop.example.com'];

function server(req) {
  const headers = {};
  if (allowed.includes(req.origin)) {
    headers['Access-Control-Allow-Origin'] = req.origin;
    headers['Access-Control-Allow-Methods'] = 'GET,POST';
  }
  if (req.method === 'OPTIONS') return { status: 204, headers }; // preflight
  return { status: 200, headers, body: 'data' };
}

function browserFetch(origin, method) {
  const res = server({ origin, method });
  const ok = res.headers['Access-Control-Allow-Origin'] === origin;
  return ok ? 'OK -> ' + res.body : 'BLOCKED by browser: CORS policy';
}

console.log(browserFetch('https://shop.example.com', 'GET')); // OK -> data
console.log(browserFetch('https://evil.example.org', 'GET')); // BLOCKED by browser: CORS policy

