// Simulation: one thread handling 3 slow I/O requests (Node style) vs one blocking worker per request
const io = (name, ms) => new Promise(r => setTimeout(() => r(name + ' done'), ms)); // DB / API call

async function nodeStyle() {
  const t0 = Date.now();
  const res = await Promise.all([io('req1', 100), io('req2', 100), io('req3', 100)]);
  console.log(res, '~' + Math.round((Date.now() - t0) / 100) * 100 + 'ms total');
  // [ 'req1 done', 'req2 done', 'req3 done' ] ~100ms total (I/O overlaps on one thread)
}

function cpuHeavy() { const end = Date.now() + 200; while (Date.now() < end) {} return 'cpu done'; }

nodeStyle().then(() => {
  const t0 = Date.now();
  cpuHeavy(); // blocks the event loop: every other request waits (use workers, or a different stack)
  console.log('cpu task blocked everyone for ~' + (Math.round((Date.now() - t0) / 100) * 100) + 'ms'); // ~200ms
});

// Simulation: a middleware pipeline like Express's app.use
function createApp() {
  const stack = [];
  return {
    use: fn => stack.push(fn),
    handle(req) {
      let i = 0;
      const res = { status: 200, body: null };
      const next = () => { const fn = stack[i++]; if (fn) fn(req, res, next); };
      next();
      return res;
    },
  };
}

const app = createApp();
app.use((req, res, next) => { console.log('log:', req.path); next(); });
app.use((req, res, next) => {
  if (!req.token) { res.status = 401; res.body = 'Unauthorized'; return; } // stop the chain
  next();
});
app.use((req, res) => { res.body = 'secret data'; });

console.log(app.handle({ path: '/orders', token: 'abc' }));
// log: /orders -> { status: 200, body: 'secret data' }
