// Simulation: over-fetching in REST vs asking only for what you need in GraphQL
const db = { id: 1, name: 'Ali', email: 'ali@x.com', address: 'Cairo', orders: [{ id: 10, total: 120 }] };

// REST: fixed response per endpoint
const restGetUser = () => ({ ...db });
console.log(Object.keys(restGetUser()).length, 'fields sent'); // 5 fields sent

// GraphQL-like: client lists fields, server returns exactly those
function query(fields) {
  const pick = (obj, f) => Object.fromEntries(Object.entries(f).map(([k, v]) =>
    [k, v === true ? obj[k] : obj[k].map(x => pick(x, v))]));
  return pick(db, fields);
}
console.log(query({ name: true, orders: { total: true } }));
// { name: 'Ali', orders: [ { total: 120 } ] }  (one request, no extra fields)

// Pick the right status code for each outcome
const users = new Map([[1, { id: 1, name: 'Ali' }]]);

function handle(method, path, body) {
  const id = Number(path.split('/')[2]);
  if (method === 'GET')    return users.has(id) ? [200, users.get(id)] : [404, { error: 'Not found' }];
  if (method === 'POST') {
    if (!body?.name) return [400, { error: 'name is required' }];
    const newId = users.size + 1; users.set(newId, { id: newId, ...body });
    return [201, users.get(newId)];
  }
  if (method === 'DELETE') return users.delete(id) ? [204, null] : [404, { error: 'Not found' }];
  return [405, { error: 'Method not allowed' }];
