function charge(idempotencyKey, amount) {
  if (processed.has(idempotencyKey)) return { ...processed.get(idempotencyKey), replayed: true };
  totalCharged += amount;
  const result = { chargeId: 'ch_' + (processed.size + 1), amount };
  processed.set(idempotencyKey, result);
  return result;
}
