from datetime import date, timedelta

class Subscription:
    def __init__(self, plan, price, start):
        self.plan, self.price, self.status = plan, price, 'active'
        self.next_billing = start + timedelta(days=30)

    def renew(self, today, card_ok):
        if today < self.next_billing:
            return 'not due yet'
        if card_ok:
            self.next_billing += timedelta(days=30)
            return 'charged ' + str(self.price)
        self.status = 'past_due'
        return 'payment failed -> past_due'

sub = Subscription('Pro', 99, date(2026, 1, 1))
print(sub.renew(date(2026, 1, 15), True))   # not due yet
print(sub.renew(date(2026, 2, 1), True))    # charged 99
print(sub.next_billing)                     # 2026-03-02
print(sub.renew(date(2026, 3, 4), False))   # payment failed -> past_due
print(sub.status)                           # past_due

