// Multi-tenancy (shared DB, tenant_id column): every query must be scoped
const invoices = [
  { id: 1, tenantId: 'acme',   total: 100 },
  { id: 2, tenantId: 'globex', total: 250 },
  { id: 3, tenantId: 'acme',   total: 75 }
];
// Wrong: forgets the tenant filter -> data leak between customers
