// Scaling basics: round-robin load balancer + cache in front of the DB
const servers = ['app-1', 'app-2', 'app-3'];
let next = 0;
const balance = () => servers[next++ % servers.length];

const cache = new Map();
let dbQueries = 0;
const getReport = id => {
  if (!cache.has(id)) { dbQueries++; cache.set(id, 'report ' + id); }
  return cache.get(id);
};
const hits = {};
for (let i = 0; i < 9; i++) {
  const s = balance();
  hits[s] = (hits[s] || 0) + 1;
  getReport(i % 3); // only 3 distinct reports requested
}
