// Custom errors + one central handler (like an Express error middleware)
class AppError extends Error {
  constructor(message, status) { super(message); this.status = status; this.name = 'AppError'; }
}
class NotFound extends AppError { constructor(what) { super(what + ' not found', 404); } }

function getUser(id) {
  if (id !== 1) throw new NotFound('User ' + id);
  return { id, name: 'Ali' };
}
function handle(fn) {
  try { return { status: 200, body: fn() }; }
  catch (e) {
    if (e instanceof AppError) return { status: e.status, body: { error: e.message } };
    console.error('unexpected:', e);           // log the real cause
    return { status: 500, body: { error: 'Internal error' } }; // hide details from user
  }
}
console.log(handle(() => getUser(1))); // { status: 200, body: { id: 1, name: 'Ali' } }
console.log(handle(() => getUser(9))); // { status: 404, body: { error: 'User 9 not found' } }
console.log(handle(() => null.x));     // { status: 500, ... }

import { Component, useState } from 'react';

class ErrorBoundary extends Component {
  state = { hasError: false };
  static getDerivedStateFromError() { return { hasError: true }; }
  componentDidCatch(error) { console.log('Logged:', error.message); }
  render() {
    if (this.state.hasError) {
      return <div><p>Something went wrong.</p><button onClick={() => this.setState({ hasError: false })}>Try again</button></div>;
    }
    return this.props.children;
  }
}

function Buggy() {
  const [boom, setBoom] = useState(false);
  if (boom) throw new Error('Render crashed!');
  return <button onClick={() => setBoom(true)}>Crash this widget</button>;
}

function App() {
  return (
    <div style={{ fontFamily: 'sans-serif' }}>
      <h3>Dashboard (still alive)</h3>
      <ErrorBoundary><Buggy /></ErrorBoundary>
    </div>
  );
}

