// Simulation: core Redis commands - SET with TTL, INCR counter, sorted-set leaderboard
const store = new Map();
let clock = 0; // fake seconds
const redis = {
  set(k, v, ex) { store.set(k, { v, exp: ex ? clock + ex : Infinity }); },
  get(k) { const e = store.get(k); return e && e.exp > clock ? e.v : null; },
  incr(k) { const n = (this.get(k) || 0) + 1; this.set(k, n); return n; },
  zadd(k, score, m) { const z = this.get(k) || {}; z[m] = score; this.set(k, z); },
  ztop(k, n) { const z = this.get(k) || {}; return Object.entries(z).sort((a, b) => b[1] - a[1]).slice(0, n); }
};
redis.set('session:1', 'ali', 60);
console.log(redis.get('session:1')); // ali
clock = 61;
console.log(redis.get('session:1')); // null (expired)
redis.incr('visits'); redis.incr('visits');
console.log(redis.get('visits')); // 2
redis.zadd('board', 90, 'Sara'); redis.zadd('board', 120, 'Omar');
console.log(redis.ztop('board', 1)); // [ [ 'Omar', 120 ] ]

// Simulation: a CDN edge cache serving a static file near the user
const origin = { requests: 0, fetch(path) { this.requests++; return 'content of ' + path; } };
const edges = { dubai: new Map(), london: new Map() };

function request(edgeName, path) {
  const edge = edges[edgeName];
  if (edge.has(path)) return edgeName + ': HIT  ' + path;
  edge.set(path, origin.fetch(path));
  return edgeName + ': MISS ' + path + ' (fetched from origin)';
}
console.log(request('dubai', '/logo.png'));  // dubai: MISS /logo.png (fetched from origin)
console.log(request('dubai', '/logo.png'));  // dubai: HIT  /logo.png
console.log(request('dubai', '/logo.png'));  // dubai: HIT  /logo.png
console.log(request('london', '/logo.png')); // london: MISS /logo.png (fetched from origin)
console.log('origin requests:', origin.requests); // origin requests: 2 (not 4)

