function makeNode(name, parent = null) {
  return { name, parent, handlers: [], on(fn) { this.handlers.push(fn); } };
}
function dispatch(target) {
  let node = target;
  while (node) { // bubble from target up to root
    node.handlers.forEach((fn) => fn({ target, currentTarget: node }));
    node = node.parent;
  }
}

