class Emitter {
  private subs: ((d: string) => void)[] = [];
  subscribe(fn: (d: string) => void) { this.subs.push(fn); }
  emit(d: string) { this.subs.forEach(fn => fn(d)); }
}
const e = new Emitter();
e.subscribe(d => console.log('A got ' + d));
e.subscribe(d => console.log('B got ' + d));
e.emit('order-created');   // A got order-created, then B got order-created

