// Simulation: Virtual DOM diffing - compare old and new trees, apply only the changes
const oldTree = { tag: 'ul', children: [
  { tag: 'li', text: 'Apples' }, { tag: 'li', text: 'Milk' }, { tag: 'li', text: 'Eggs' } ] };
const newTree = { tag: 'ul', children: [
  { tag: 'li', text: 'Apples' }, { tag: 'li', text: 'Bread' }, { tag: 'li', text: 'Eggs' } ] };

function diff(a, b) {
  const patches = [];
  b.children.forEach((child, i) => {
    if (!a.children[i]) patches.push('CREATE li #' + i);
    else if (a.children[i].text !== child.text)
      patches.push('UPDATE li #' + i + ': ' + a.children[i].text + ' -> ' + child.text);
  });
  return patches;
}

const patches = diff(oldTree, newTree);
console.log(patches); // [ 'UPDATE li #1: Milk -> Bread' ]
console.log('DOM operations needed:', patches.length); // 1 (not a full re-render)

