import { useState, useEffect } from 'react';

// Simulation: a fake socket with the same on/off API as socket.io-client
function createFakeSocket() {
  const handlers = {}; let timer;
  return {
    on: (ev, fn) => { handlers[ev] = fn; },
    off: (ev) => { delete handlers[ev]; },
    connect() { timer = setInterval(() => handlers.message && handlers.message('Order #' + Math.floor(Math.random() * 100)), 1500); },
    disconnect() { clearInterval(timer); console.log('socket disconnected'); },
  };
}

function App() {
  const [messages, setMessages] = useState([]);
  useEffect(() => {
    const socket = createFakeSocket();
    socket.on('message', (m) => setMessages((prev) => [...prev, m]));
    socket.connect();
    return () => { socket.off('message'); socket.disconnect(); }; // always clean up
  }, []);
  return <ul>{messages.map((m, i) => <li key={i}>{m}</li>)}</ul>;
}

