import { useReducer } from 'react';

const initial = { items: [], total: 0 };
function cartReducer(state, action) {
  switch (action.type) {
    case 'add':
      return { items: [...state.items, action.item], total: state.total + action.item.price };
    case 'clear':
      return initial;
    default:
      return state;
  }
}

function App() {
  const [cart, dispatch] = useReducer(cartReducer, initial);
  return (
    <div>
      <button onClick={() => dispatch({ type: 'add', item: { name: 'Book', price: 120 } })}>Add book</button>
      <button onClick={() => dispatch({ type: 'clear' })}>Clear</button>
      <p>{cart.items.length} items, total {cart.total} EGP</p>
    </div>
  );
}

