}

// Next.js (SSR/SSG): server renders the component to HTML first
function ssrResponse(p) {
  return '<div id="root"><h1>' + p.name + '</h1><p>$' + p.price + '</p></div><script src="/bundle.js"></script>';
}

console.log("CSR  ->", csrResponse());
