// Simulation: the four rendering strategies and WHEN the HTML is produced
let dbTitle = "Launch Sale";
let renderCount = 0;
const render = () => { renderCount++; return "<h1>" + dbTitle + "</h1> (render #" + renderCount + ")"; };

// SSG: render once at build time
const ssgPage = render();
// SSR: render on every request
const ssr = () => render();
// ISR: reuse cached page, regenerate if older than revalidate seconds
let isrCache = { html: render(), at: 0 };
const isr = (now, revalidate) => {
  if (now - isrCache.at >= revalidate) isrCache = { html: render(), at: now };
  return isrCache.html;
};
// CSR: server sends shell, browser fetches data later
const csr = () => "<div id=root></div> + client fetch";

dbTitle = "Black Friday Sale"; // data changes after build
console.log("SSG :", ssgPage);           // <h1>Launch Sale</h1> (render #1)  stale!
console.log("SSR :", ssr());             // <h1>Black Friday Sale</h1> (render #3)
console.log("ISR t=5  :", isr(5, 60));   // cached: <h1>Launch Sale</h1> (render #2)
console.log("ISR t=65 :", isr(65, 60));  // regenerated: <h1>Black Friday Sale</h1> (render #4)
console.log("CSR :", csr());

// Simulation: how a file path maps to a route in each router
const appRouterFiles = [
  "app/page.tsx",
  "app/blog/page.tsx",
  "app/blog/[slug]/page.tsx",
  "app/blog/layout.tsx",       // layout, not a route
  "app/api/users/route.ts",
];
const pagesRouterFiles = [
  "pages/index.tsx",
  "pages/blog/index.tsx",
  "pages/blog/[slug].tsx",
  "pages/api/users.ts",
];

function appRoute(f) {
  const m = f.match(/^app\/(.*?)\/?(page|route)\.(tsx|ts)$/); // only page/route files create URLs
  if (!m) return null;
  return "/" + m[1] + (m[2] === "route" ? "  (API handler)" : "");
}
function pagesRoute(f) {
  const route = f.replace(/^pages/, "").replace(/\.(tsx|ts)$/, "").replace(/\/index$/, "");
  return route || "/";
}

