// Simulation: matching URLs against dynamic route patterns like [slug] and [...rest]
const routes = [
  { file: "app/blog/[slug]/page.tsx", pattern: "/blog/[slug]" },
  { file: "app/shop/[...parts]/page.tsx", pattern: "/shop/[...parts]" },
  { file: "app/docs/[[...parts]]/page.tsx", pattern: "/docs/[[...parts]]" },
];

function match(url, pattern) {
  const u = url.split("/").filter(Boolean);
  const p = pattern.split("/").filter(Boolean);
  const params = {};
  for (let i = 0; i < p.length; i++) {
    const seg = p[i];
    if (seg.startsWith("[[...")) { params[seg.slice(5, -2)] = u.slice(i); return params; }
    if (seg.startsWith("[...")) {
      if (u.length <= i) return null; // needs at least one segment
      params[seg.slice(4, -1)] = u.slice(i); return params;
    }
    if (seg.startsWith("[")) { if (!u[i]) return null; params[seg.slice(1, -1)] = u[i]; continue; }
    if (u[i] !== seg) return null;
  }
  return u.length === p.length ? params : null;
}

for (const url of ["/blog/hello-world", "/shop/men/shoes/42", "/docs", "/docs/a/b", "/blog"]) {
  const hit = routes.map(r => ({ r, params: match(url, r.pattern) })).find(x => x.params);
  console.log(url, "->", hit ? hit.r.file + " " + JSON.stringify(hit.params) : "404");
}
