function optimize(img, deviceWidth, acceptHeader) {
  const width = [320, 640, 1080, 1920].find(w => w >= deviceWidth) ?? 1920;
  const format = acceptHeader.includes("image/avif") ? "avif"
               : acceptHeader.includes("image/webp") ? "webp" : "jpg";
  const ratio = width / img.width;
  const factor = { avif: 0.3, webp: 0.4, jpg: 0.7 }[format];
  return {
    url: "/_next/image?url=" + encodeURIComponent(img.src) + "&w=" + width + "&q=75",
    format, width, height: Math.round(img.height * ratio),
    kb: Math.round(img.bytes * ratio * ratio * factor / 1024),
  };
}

