// A tiny EventEmitter, the same idea as require('events')
class EventEmitter {
  constructor() { this.events = {}; }
  on(name, fn) { (this.events[name] ||= []).push(fn); return this; }
  once(name, fn) { const w = (...a) => { this.off(name, w); fn(...a); }; return this.on(name, w); }
  off(name, fn) { this.events[name] = (this.events[name] || []).filter(f => f !== fn); }
  emit(name, ...args) {
    (this.events[name] || []).slice().forEach(fn => fn(...args));
    return (this.events[name] || []).length > 0;
  }
}
