// Leak: a cache that only grows. Fix: bound it (evict the oldest) or use WeakMap.
const leaky = new Map();
const bounded = new Map();
const LIMIT = 100;
function handle(userId, leakyMode) {
  const data = { id: userId, payload: new Array(100).fill(userId) };
  if (leakyMode) leaky.set(userId, data);          // never removed
  else {
    bounded.set(userId, data);
    if (bounded.size > LIMIT) bounded.delete(bounded.keys().next().value); // evict oldest
  }
}
for (let i = 0; i < 10000; i++) { handle(i, true); handle(i, false); }
console.log('leaky size:', leaky.size);     // leaky size: 10000
console.log('bounded size:', bounded.size); // bounded size: 100
