// Simulation: CPU-heavy work on the single thread freezes everything else (timers, other requests)
let ticks = 0;
const timer = setInterval(() => ticks++, 20);

function cpuHeavy(ms) { const end = Date.now() + ms; while (Date.now() < end) {} }

setTimeout(() => {
  const before = ticks;
  cpuHeavy(300);                                  // e.g. video encoding or a huge JSON parse
  console.log('ticks during heavy task:', ticks - before); // 0 (the loop was frozen)
  clearInterval(timer);
  console.log('Use workers, a queue, or another language for CPU-bound jobs');
}, 100);
