// Simulation: a tiny Dependency Injection container (what Nest's IoC container does)
class Container {
  private registry = new Map<string, { factory: (c: Container) => any; instance?: any }>();
  register(name: string, factory: (c: Container) => any) { this.registry.set(name, { factory }); }
  resolve<T = any>(name: string): T {
    const entry = this.registry.get(name);
    if (!entry) throw new Error("No provider for " + name);
    if (!entry.instance) entry.instance = entry.factory(this); // singleton
    return entry.instance;
  }
}

