// Simulation: module boundaries - a provider is only visible if exported and the module is imported
class Module {
  constructor(public name: string, public providers: Record<string, any>, public exports: string[] = [], public imports: Module[] = []) {}
  get(name: string): any {
    if (name in this.providers) return this.providers[name];                          // own provider
    for (const imp of this.imports) if (imp.exports.includes(name)) return imp.get(name); // imported + exported
    throw new Error(this.name + " cannot resolve " + name + " (not provided, or not exported by an imported module)");
