// Simulation: request lifecycle order in NestJS
const log = [];
const step = (name) => (next) => { log.push(name + " (in)"); const r = next(); log.push(name + " (out)"); return r; };

function handleRequest() {
  const pipeline = [
    step("Middleware"),
    step("Guard"),
    step("Interceptor"),
    step("Pipe"),
  ];
  const controller = () => { log.push("Controller handler"); return "result"; };
  // Compose: each stage wraps the next
  const run = pipeline.reduceRight((next, stage) => () => stage(next), controller);
  return run();
}

handleRequest();
console.log(log.join("\n"));
// Middleware (in), Guard (in), Interceptor (in), Pipe (in), Controller handler,
// then unwinding: Pipe (out), Interceptor (out), Guard (out), Middleware (out)
console.log("Exception filters wrap the whole thing and catch any thrown error.");

// Simulation: Middleware vs Guard vs Pipe vs Interceptor - each has a different job
type Req = { headers: { authorization?: string }; body: any; user?: string };

const middleware = (req: Req) => { console.log("middleware: log request"); };                  // generic, before routing
const guard = (req: Req) => {                                                                  // allow / deny
  if (req.headers.authorization !== "Bearer ok") throw new Error("403 Forbidden (guard)");
  req.user = "ahmed";
};
const pipe = (value: any) => {                                                                 // validate / transform input
  const n = Number(value.qty);
  if (Number.isNaN(n)) throw new Error("400 qty must be a number (pipe)");
  return { qty: n };
};
const interceptor = (handler: () => any) => {                                                  // wrap before + after
  const out = handler();
  console.log("interceptor: wrapping response");
  return { data: out };
};

function request(req: Req) {
  try {
    middleware(req); guard(req);
    const dto = pipe(req.body);
    console.log("->", JSON.stringify(interceptor(() => "ordered " + dto.qty + " items")));
  } catch (e) { console.log("->", e.message); }
}
request({ headers: {}, body: { qty: "2" } });                               // 403 (guard)
request({ headers: { authorization: "Bearer ok" }, body: { qty: "abc" } }); // 400 (pipe)
request({ headers: { authorization: "Bearer ok" }, body: { qty: "3" } });   // {"data":"ordered 3 items"}

// Simulation: ValidationPipe - declarative rules (like class-validator) applied to a DTO
type Rule = (v: any) => string | null;
const IsEmail: Rule = v => /^\S+@\S+\.\S+$/.test(v) ? null : "email must be a valid email";
const MinLength = (n: number): Rule => v => typeof v === "string" && v.length >= n ? null : "must be longer than or equal to " + n + " characters";
const IsInt: Rule = v => Number.isInteger(v) ? null : "age must be an integer";

const CreateUserDto = { email: [IsEmail], password: [MinLength(8)], age: [IsInt] };

function validationPipe(dto: Record<string, Rule[]>, body: any) {
  const errors: string[] = [];
  for (const [field, rules] of Object.entries(dto)) {
    for (const rule of rules) { const err = rule(body[field]); if (err) errors.push(field + ": " + err); }
  }
  // whitelist: strip unknown properties
  const clean = Object.fromEntries(Object.keys(dto).map(k => [k, body[k]]));
  if (errors.length) return { statusCode: 400, message: errors };
  return { statusCode: 201, body: clean };
}

