class Injector {
  private singleton?: Counter;
  constructor(private scope: Scope) {}
  resolve(requestCtx: { cache?: Counter }) {
    if (this.scope === "DEFAULT") return (this.singleton ??= new Counter());
    if (this.scope === "REQUEST") return (requestCtx.cache ??= new Counter());
    return new Counter(); // TRANSIENT: new for each injection
  }
}

