// Simulation: circular dependency and the forwardRef fix (lazy reference)
class Container {
  private instances = new Map<string, any>();
  private resolving = new Set<string>();
  constructor(private defs: Record<string, (get: (n: string) => any) => any>) {}
  get = (name: string): any => {
    if (this.instances.has(name)) return this.instances.get(name);
    if (this.resolving.has(name)) throw new Error("Nest can't resolve dependencies: circular dependency at " + name);
    this.resolving.add(name);
    const inst = this.defs[name](this.get);
    this.resolving.delete(name); this.instances.set(name, inst);
    return inst;
  };
}

