  { id: 1, email: "admin@x.com", password: "pass", roles: ["admin"] },
  { id: 2, email: "user@x.com", password: "pass", roles: ["user"] },
];
const sessions = new Map<string, User>();   // stands in for JWT verification

function login(email: string, password: string) {            // AuthService.signIn
  const u = users.find(x => x.email === email && x.password === password);
  if (!u) return { status: 401, message: "Unauthorized" };
  const token = "token-" + u.id;
  sessions.set(token, u);
  return { status: 200, access_token: token };
}

const rolesGuard = (required: string[]) => (token?: string) => {   // AuthGuard + RolesGuard
  const user = token && sessions.get(token);
  if (!user) return { status: 401, message: "Unauthorized" };
  if (!required.some(r => user.roles.includes(r))) return { status: 403, message: "Forbidden" };
  return { status: 200, message: "Welcome " + user.email };
};

