    if (!items.has(id)) throw new NotFoundException("Item " + id + " not found");
    return items.get(id);
  },
  crash() { throw new TypeError("db connection lost"); },
};

// Global exception filter
function exceptionFilter(fn: () => any, path: string) {
  try { return { status: 200, body: fn() }; }
  catch (e) {
    if (e instanceof HttpException)
      return { status: e.status, body: { statusCode: e.status, message: e.message, path } };
    console.error("unexpected:", e.message);                                                   // log internally
    return { status: 500, body: { statusCode: 500, message: "Internal server error", path } }; // hide details
  }
}

