class Money:
    def __init__(self, amount, cur="EGP"):
        self.amount, self.cur = amount, cur
    def __repr__(self):
        return f"Money({self.amount}, {self.cur!r})"
    def __str__(self):
        return f"{self.amount} {self.cur}"
    def __add__(self, other):
        return Money(self.amount + other.amount, self.cur)
    def __eq__(self, other):
        return (self.amount, self.cur) == (other.amount, other.cur)
    def __lt__(self, other):
        return self.amount < other.amount
    def __bool__(self):
        return self.amount != 0
    def __hash__(self):
        return hash((self.amount, self.cur))

