class PaymentError(Exception):
    pass

class InsufficientFunds(PaymentError):
    def __init__(self, needed):
        super().__init__(f"need {needed} more")
        self.needed = needed

def charge(balance, amount):
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > balance:
        raise InsufficientFunds(amount - balance)
    return balance - amount

for amount in (50, 500, -1):
    try:
        left = charge(100, amount)
    except InsufficientFunds as e:
        print("short by", e.needed)      # short by 400
    except (ValueError, PaymentError) as e:
        print("bad request:", e)         # bad request: amount must be positive
    else:
        print("ok, left", left)          # ok, left 50
    finally:
        print("audit logged")            # printed 3 times

try:
    try:
        int("abc")
    except ValueError as e:
        raise PaymentError("parse failed") from e
except PaymentError as e:
