// Simulation: old bridge (async JSON messages) vs JSI (direct synchronous call)
const nativeBattery = { getLevel: () => 87 };

// Old architecture: serialize -> queue -> deserialize, always async
function bridgeCall(method, args) {
  const msg = JSON.stringify({ method, args });
  console.log('bridge sent:', msg); // bridge sent: {"method":"getLevel","args":[]}
  return new Promise((resolve) => {
    setTimeout(() => resolve(nativeBattery[JSON.parse(msg).method](...args)), 10);
  });
}

// New architecture (JSI): JS holds a reference to the native function
const jsiBattery = nativeBattery;

bridgeCall('getLevel', []).then((v) => console.log('bridge result:', v)); // prints last: bridge result: 87
console.log('JSI result:', jsiBattery.getLevel()); // JSI result: 87 (immediate, synchronous)
console.log('end of script'); // end of script

