// Simulation: Metro walks the import graph from the entry file and builds one bundle
const files = {
  'index.js': { imports: ['App.js'], code: "console.log('index starts')" },
  'App.js': { imports: ['Cart.js', 'api.js'], code: "console.log('App loaded')" },
  'Cart.js': { imports: ['api.js'], code: "console.log('Cart loaded')" },
  'api.js': { imports: [], code: "console.log('api loaded')" },
};

function bundle(entry, seen = new Set(), order = []) {
  if (seen.has(entry)) return order;
  seen.add(entry);
  files[entry].imports.forEach((dep) => bundle(dep, seen, order));
  order.push(entry); // dependencies come first
  return order;
}

const order = bundle('index.js');
console.log('Bundle order:', order.join(', '));
