// Simulation: how a deep link becomes route + params (what Expo Router does for app/product/[id].tsx)
const routes = ['/product/[id]', '/order/[orderId]/track', '/'];

function matchRoute(url) {
  const { pathname, searchParams } = new URL(url);
  const parts = pathname.split('/').filter(Boolean);
  for (const route of routes) {
    const rParts = route.split('/').filter(Boolean);
    if (rParts.length !== parts.length) continue;
    const params = {};
    const ok = rParts.every((p, i) => {
      if (p.startsWith('[')) { params[p.slice(1, -1)] = parts[i]; return true; }
      return p === parts[i];
    });
    if (ok) return { route, params, query: Object.fromEntries(searchParams) };
  }
  return null;
}

console.log(matchRoute('https://shop.example.com/product/42?ref=email'));
