function registerToken(userId, token) { server.tokens.set(userId, token); } // tokens can change: update on every launch

function sendPush(userId, text) {
  const token = server.tokens.get(userId);
  if (!token) return 'No token: user denied permission or never registered';
  const provider = token.startsWith('APNs') ? 'APNs' : 'FCM';
