// Simulation: cancel a stale request with AbortController (user leaves the screen)
function fakeFetch(url, { signal }) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => resolve({ url, data: ['order 1', 'order 2'] }), 500);
    signal.addEventListener('abort', () => {
      clearTimeout(timer);
      reject(new DOMException('Request cancelled', 'AbortError'));
    });
  });
}

