function checkForUpdate(app) {
  const compatible = server.filter((u) => u.runtimeVersion === app.runtimeVersion);
  const latest = compatible[compatible.length - 1];
  if (latest && latest.bundle !== app.bundle) return 'Download ' + latest.bundle + ': ' + latest.note;
  const needsStore = server.some((u) => u.runtimeVersion !== app.runtimeVersion);
  return needsStore ? 'Up to date for this build. Newer native build needs store release' : 'Up to date';
}

